// ═══════════════════════════════════════════════════════════
// FILTRAR Y PREPARAR TICKERS DINÁMICAMENTE DESDE LA HOJA
// ═══════════════════════════════════════════════════════════

const rows = $input.all();
const validStocks = [];

for (const r of rows) {
  const row = r.json;
  const ticker = (row.Ticker || '').trim();

  // Ignorar fila de totales o vacías
  if (!ticker || ticker.toLowerCase().includes('total')) {
    continue;
  }

  // Prioridad: Columna DIR_COTIZACION. Si viene vacía, fallback a Ticker + .CL
  let symbol = (row.DIR_COTIZACION || '').trim();
  if (!symbol) {
    symbol = row.Mercado === 'USD' ? ticker : `${ticker}.CL`;
  }

  const qty = parseFloat(row.Cantidad) || 1;
  const precioActualPrevio = parseFloat(row['Precio Mercado Actual']) || 0;
  const trm = parseFloat(row.TRM) || 1;
  const moneda = (row.Moneda || 'COP').toUpperCase();
  const costoOrigen = parseFloat(row['Inversión Inicial (Moneda Origen)']) || (parseFloat(row['Precio Promedio Compra']) * qty) || 0;

  validStocks.push({
    json: {
      Ticker: ticker,
      DIR_COTIZACION: symbol,
      Nombre: row.Nombre || ticker,
      Mercado: row.Mercado || 'BVC',
      Moneda: moneda,
      TRM: trm,
      Cantidad: qty,
      precioActualPrevio: precioActualPrevio,
      costoOrigen: costoOrigen,
      url: `https://query1.finance.yahoo.com/v8/finance/chart/${encodeURIComponent(symbol)}?interval=1d&range=1d`
    }
  });
}

return validStocks;

// ═══════════════════════════════════════════════════════════
// PROCESAR RESPUESTAS Y UNIFICAR VALORIZACIÓN BIMONEDA
// ═══════════════════════════════════════════════════════════

const stockItems = $('2. Preparar Consultas Yahoo').all();
const httpResponses = $input.all();
const now = new Date();
const fechaHora = now.toLocaleString('sv-SE', { timeZone: 'America/Bogota' }).replace('T', ' ');

const processedList = [];

for (let i = 0; i < stockItems.length; i++) {
  const stock = stockItems[i].json;
  const resp = httpResponses[i]?.json;

  let livePrice = stock.precioActualPrevio;
  let prevClose = stock.precioActualPrevio;
  let variacionPct = 0;
  let variacionDivisa = 0;
  let volumen = 0;

  if (resp?.chart?.result?.[0]?.meta) {
    const meta = resp.chart.result[0].meta;
    const apiPrice = meta.regularMarketPrice;
    const apiClose = meta.chartPreviousClose || meta.previousClose || apiPrice;

    if (typeof apiPrice === 'number' && apiPrice > 0) {
      livePrice = apiPrice;
      prevClose = apiClose;
      variacionDivisa = Math.round((livePrice - prevClose) * 100) / 100;
      if (prevClose > 0) {
        variacionPct = Math.round(((livePrice - prevClose) / prevClose) * 10000) / 10000;
      }
      volumen = meta.regularMarketVolume || 0;
    }
  }

  // Conversión homogénea a COP para el resumen patrimonial
  const factorTRM = stock.Moneda === 'USD' ? (stock.TRM || 4150) : 1;
  const valorMercadoCOP = Math.round((livePrice * stock.Cantidad * factorTRM) * 100) / 100;
  const costoBaseCOP = Math.round((stock.costoOrigen * factorTRM) * 100) / 100;

  processedList.push({
    json: {
      fechaHora,
      Ticker: stock.Ticker,
      DIR_COTIZACION: stock.DIR_COTIZACION,
      Nombre: stock.Nombre,
      Mercado: stock.Mercado,
      Moneda: stock.Moneda,
      livePrice,
      prevClose,
      variacionDivisa,
      variacionPct,
      volumen,
      Cantidad: stock.Cantidad,
      valorMercadoCOP,
      costoBaseCOP
    }
  });
}

return processedList;

// Mapeo para Portafolio_Base: Col J ('Precio Mercado Actual') y Col S ('Variación Día (%)')
const items = $input.all();

return items.map(item => ({
  json: {
    Ticker: item.json.Ticker,
    'Precio Mercado Actual': item.json.livePrice,
    'Variación Día (%)': item.json.variacionPct
  }
}));

// Mapeo para Historico_Precios_Activos (9 columnas requeridas)
const items = $('4. Procesar Métricas y Bimoneda').all();

return items.map(item => ({
  json: {
    'Fecha y Hora': item.json.fechaHora,
    'Ticker': item.json.Ticker,
    'Nombre': item.json.Nombre,
    'Mercado': item.json.Mercado,
    'Precio Actual (COP)': item.json.livePrice,
    'Cierre Previo (COP)': item.json.prevClose,
    'Variación Día (COP)': item.json.variacionDivisa,
    'Variación Día (%)': item.json.variacionPct,
    'Volumen': item.json.volumen
  }
}));

// Mapeo para Historico_Snapshots (Consolidado Patrimonial Homogéneo en COP)
const items = $('4. Procesar Métricas y Bimoneda').all();

// Ajustar estos saldos fijos de ser necesario
const FONDOS_TRII_COP = 0.00;
const EFECTIVO_DISPONIBLE_COP = 0.00;

let totalInversionInicialCOP = 0;
let totalValorMercadoCOP = 0;

for (const i of items) {
  const d = i.json;
  totalInversionInicialCOP += d.costoBaseCOP;
  totalValorMercadoCOP += d.valorMercadoCOP;
}

totalInversionInicialCOP = Math.round(totalInversionInicialCOP * 100) / 100;
totalValorMercadoCOP = Math.round(totalValorMercadoCOP * 100) / 100;
const patrimonioTotalCOP = Math.round((totalValorMercadoCOP + FONDOS_TRII_COP + EFECTIVO_DISPONIBLE_COP) * 100) / 100;
const rendimientoPct = Math.round(((totalValorMercadoCOP - totalInversionInicialCOP) / totalInversionInicialCOP) * 10000) / 10000;

const fechaHora = items[0].json.fechaHora;

return [{
  json: {
    'Fecha y Hora': fechaHora,
    'Inversión Inicial (COP)': totalInversionInicialCOP,
    'Valor Mercado Acciones/ETFs (COP)': totalValorMercadoCOP,
    'Fondos Trii (COP)': FONDOS_TRII_COP,
    'Saldo Efectivo (COP)': EFECTIVO_DISPONIBLE_COP,
    'Patrimonio Total (COP)': patrimonioTotalCOP,
    'Rendimiento %': rendimientoPct
  }
}];

// ═══════════════════════════════════════════════════════════
// CONSTRUCCIÓN DEL MENSAJE EJECUTIVO PARA TELEGRAM (BIMONEDA)
// ═══════════════════════════════════════════════════════════

const snap = $('Preparar Historico_Snapshots').first().json;
const metrics = $('4. Procesar Métricas y Bimoneda').all().map(i => i.json);

const fmtCOP = (val) => '$ ' + Math.round(val).toLocaleString('es-CO');
const fmtPct = (val) => (val >= 0 ? '+' : '') + (val * 100).toFixed(2) + '%';

// Ordenar por variación diaria
const ordenados = [...metrics].sort((a, b) => b.variacionPct - a.variacionPct);
const topGanadora = ordenados[0];
const topPerdedora = ordenados[ordenados.length - 1];

// Activos en USD para reporte especial
const activosUSD = metrics.filter(m => m.Moneda === 'USD');
const resumenUSD = activosUSD.map(a => `• <b>${a.Ticker}:</b> $${a.livePrice} USD (${fmtPct(a.variacionPct)})`).join('\n');

const texto = `📊 <b>Monitoreo Portafolio Trii, BVC & USA</b>
🕒 <i>${snap['Fecha y Hora']}</i>
━━━━━━━━━━━━━━━━━━━━━━
💰 <b>Patrimonio Total:</b> <code>${fmtCOP(snap['Patrimonio Total (COP)'])}</code>
📈 <b>Rendimiento Consolidado:</b> <b>${fmtPct(snap['Rendimiento %'])}</b>

💼 <b>Acciones/ETFs:</b> ${fmtCOP(snap['Valor Mercado Acciones/ETFs (COP)'])} COP
🏦 <b>Fondos:</b> ${fmtCOP(snap['Fondos Trii (COP)'])} COP
🪙 <b>Saldo Efectivo:</b> ${fmtCOP(snap['Saldo Efectivo (COP)'])} COP
━━━━━━━━━━━━━━━━━━━━━━
🇺🇸 <b>Mercado USA (Dólares):</b>
${resumenUSD || '• Sin posiciones USD'}
━━━━━━━━━━━━━━━━━━━━━━
🚀 <b>Top Subida Hoy:</b> ${topGanadora.Ticker} (<b>${fmtPct(topGanadora.variacionPct)}</b>)
🔻 <b>Mayor Caída Hoy:</b> ${topPerdedora.Ticker} (<b>${fmtPct(topPerdedora.variacionPct)}</b>)
━━━━━━━━━━━━━━━━━━━━━━
✅ <i>Google Sheets actualizado exitosamente.</i>`;

return [{
  json: {
    chatId: 'TU_TELEGRAM_CHAT_ID_AQUI',
    mensaje: texto
  }
}];
